const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
setTimeout(() => broken("timed out"), 85000).unref();
process.env.WRANGLER_SEND_METRICS = "false";
process.env.CI = "true";
const root = "/tmp/proj";
fs.mkdirSync(root, { recursive: true });
fs.writeFileSync(root + "/index.js", "export default { async fetch() { return new Response('ok'); }, async email(message) { message.setReject('nope'); } };\n");
process.chdir(root);
(async () => {
  let server, result;
  try {
    const { createTestHarness } = require("wrangler");
    server = createTestHarness({ root, workers: [{ config: { name: "mail", main: "./index.js", compatibility_date: "2025-05-01" } }] });
    await server.listen();
    result = await server.getWorker().email({
      from: "sender@example.com",
      to: "inbox@example.com",
      raw: ["From: Sender <sender@example.com>", "To: Inbox <inbox@example.com>", "Message-ID: <test@example.com>", "Subject: Test email", "", "Hello from the test harness"].join("\r\n")
    });
  } catch (e) { broken("harness failed: " + (e && e.stack || e)); }
  try { await server.close(); } catch {}
  const types = Array.isArray(result && result.events) ? result.events.map((e) => e.type) : null;
  if (!types) broken("result has no events array: " + JSON.stringify(result));
  if (types.length === 1 && types[0] === "reject") symptom("email() result.events has no received event: " + JSON.stringify(types));
  if (types.length !== 2 || types[0] !== "received" || types[1] !== "reject") broken("unexpected events " + JSON.stringify(types));
  console.log("OK: email() result.events is " + JSON.stringify(types));
  process.exit(0);
})();

